def render_table_cell(renderer: 'BaseRenderer', text: str, head: bool=False, align: Optional[str]=None) ->str:
    tag = 'th' if head else 'td'
    style = ''
    if align:
        style = f' style="text-align:{align}"'
    text = renderer.render_children(renderer.inline(text))
    return f'<{tag}{style}>{text}</{tag}>\n'
